import pyomo.environ as pyo

DATA = {
    "foods": ["noodles", "protein_bar"],
    "nutrients": ["calories", "protein"],
    "cost": {"noodles": 5.0, "protein_bar": 2.5},
    "content": {
        "calories": {"noodles": 600.0, "protein_bar": 250.0},
        "protein": {"noodles": 1.5, "protein_bar": 5.0},
    },
    "requirement": {"calories": 2000.0, "protein": 16.0},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    model.servings = pyo.Var(model.FOODS, within=pyo.NonNegativeReals)

    def cost_rule(m):
        return sum(d["cost"][f] * m.servings[f] for f in m.FOODS)

    model.obj = pyo.Objective(expr=cost_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][n][f] * m.servings[f] for f in m.FOODS) >= d["requirement"][n]

    model.nutrient_requirement = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model


